import heapq


def dependency_solver(data, order, preference):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices.append([None] + versions)

    best_vector = None
    best_versions = None
    for assignment in product(*choices):
        selected = dict(zip(names, assignment))
        installed = {name for name, version in selected.items() if version is not None}
        constraints = {name: [] for name in names}
        valid = True
        for name, bounds in data["roots"].items():
            constraints[name].append(tuple(bounds))
        rows_by_name = {}
        for name in installed:
            rows_by_name[name] = next(row for row in packages[name]
                                      if row["version"] == selected[name])

        graph = {name: [] for name in installed}
        for name, row in rows_by_name.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                constraints[target].append((dep["min"], dep["max"]))
                graph[name].append(target)

        # Installed packages must be exactly the active closure of the roots.
        reachable = set()
        pending = list(data["roots"])
        while pending:
            name = pending.pop()
            if name in reachable:
                continue
            reachable.add(name)
            if name not in installed:
                valid = False
                continue
            pending.extend(graph[name])
        if not valid or reachable != installed:
            continue
        for name in installed:
            version = selected[name]
            if any(not low <= version <= high for low, high in constraints[name]):
                valid = False
                break
        if not valid:
            continue

        state, finished = set(), set()
        def visit(name):
            if name in state:
                return False
            if name in finished:
                return True
            state.add(name)
            for target in graph[name]:
                if not visit(target):
                    return False
            state.remove(name)
            finished.add(name)
            return True
        if any(not visit(name) for name in installed):
            continue

        vector = tuple(selected[name] if selected[name] is not None else -1
                       for name in order)
        if best_vector is None or (vector > best_vector if preference == "maximum"
                                   else vector < best_vector):
            best_vector = vector
            best_versions = {name: selected[name] for name in installed}
    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _dep_builder(order, preference):
    def solve(data):
        names = sorted(data["packages"], reverse=(order == "descending"))
        return dependency_solver(data, names, preference)
    return solve


def _round(n, d, mode):
    if mode == "floor":
        return n // d
    return (2 * n + d) // (2 * d)


def solve_ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        price = event["price"]
        raw = price * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, data["rounding"])
        tax = _round(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def solve_jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if ids & blocked or not mandatory <= ids:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        # Endpoints are half-open: remove endings before adding starts at a time.
        events = []
        for job in subset:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(events):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in subset)
        sorted_ids = tuple(sorted(ids))
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def solve_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start_state = (source, initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], coupons)]
            if coupons:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)), coupons - 1))
            for duration, left in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


